--
-- V001__baseline.sql — DepositAccountManagement schema (Phase 5: Deposits).
--
-- IMPORTANT PROVENANCE NOTE (deviation from every other service's V001):
-- Every other service's V001__baseline.sql is mechanically generated by
-- src/tools/gen_baselines.py from a captured pg_dump in src/scripts/. The
-- purported source for this service, src/scripts/TlDamDb.sql, IS a pg_dump
-- custom-format ("PGDMP") archive like the others, but it is only 878 bytes
-- and contains just the archive's own metadata TOC entries (ENCODING,
-- STDSTRINGS, SEARCHPATH, DATABASE) — zero CREATE TABLE/schema entries.
-- Confirmed with src/tools/pgdmp_schema.py and an independent pgdumplib
-- parse: the reference database this dump was supposed to capture was never
-- actually populated with the DepositAccountManagement schema before the
-- dump was taken. There is no ground-truth schema to recover here.
--
-- Accordingly, unlike every prior phase, this schema is HAND-DESIGNED from
-- Fineract's public domain model (the savings/FD/RD account family, interest
-- rate charts, account transfers, standing instructions, charges) rather
-- than transcribed from a captured dump. Table/column names follow this
-- repo's established conventions (uuid surrogate keys, snake_case, a
-- nullable `business_id` cross-reference column, audit columns) rather than
-- Fineract's own MySQL-oriented `m_`-prefixed names, matching how Phases 2-4
-- already adapted Fineract's domain model to this schema even when a real
-- dump existed. Status/type code *values* loosely follow Fineract's known
-- enumerations (see service header comments for the exact tables used by
-- each) but are not guaranteed byte-identical to any specific Fineract
-- version, since there is nothing to diff them against.
--
-- Applied per tenant into schema t_<tenantId> by src/tools/migrate.py
-- (which pins search_path; do NOT add SET search_path here).
--

-- ---------------------------------------------------------------------------
-- Charges catalog (shared by savings/FD/RD accounts; Customer's client_charge
-- rows reference this catalog's ids opaquely/cross-service, same as the
-- cross-service pattern already used for office_id/staff_id elsewhere).
-- ---------------------------------------------------------------------------
CREATE TABLE charge (
    id                               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    business_id                      uuid,
    name                             character varying(100) NOT NULL,
    currency_code                    character varying(3) NOT NULL,
    charge_applies_to                integer NOT NULL DEFAULT 1,   -- 1=SAVINGS (only kind this service issues)
    charge_time_type                 integer NOT NULL,             -- 1=specifiedDueDate,2=savingsActivation,5=withdrawalFee,6=annualFee,7=monthlyFee,8=overdraftFee
    charge_calculation_type          integer NOT NULL,             -- 1=flat,2=percentOfAmount
    charge_payment_mode              integer,
    amount                           numeric(19,6) NOT NULL,
    fee_on_month                     integer,
    fee_on_day                       integer,
    fee_interval                     integer,
    is_penalty                       boolean NOT NULL DEFAULT false,
    is_active                        boolean NOT NULL DEFAULT true,
    is_free_withdrawal               boolean NOT NULL DEFAULT false,
    free_withdrawal_charge_frequency integer,
    min_cap                          numeric(19,6),
    max_cap                          numeric(19,6),
    created_by                       uuid,
    created_at                       timestamptz NOT NULL DEFAULT now(),
    updated_by                       uuid,
    updated_at                       timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- Account number format catalog (per account_type, how account numbers are
-- auto-generated). Phase 5 only ever exercises account_type=SAVINGS(2) but
-- the catalog shape is generic, matching Fineract's own AccountNumberFormat.
-- ---------------------------------------------------------------------------
CREATE TABLE account_number_format (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    business_id uuid,
    account_type integer NOT NULL,  -- 1=CLIENT,2=SAVINGS,3=LOAN,4=CENTER (cross-service meanings; only SAVINGS resolved here)
    prefix_type  integer,            -- null=none,1=officeName,2=officeExternalId,3=productShortName
    created_by  uuid,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_by  uuid,
    updated_at  timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_account_number_format_type UNIQUE (account_type)
);

-- ---------------------------------------------------------------------------
-- Interest rate charts (attachable to a savings/FD/RD product to tier
-- interest by deposit amount and/or tenure).
-- ---------------------------------------------------------------------------
CREATE TABLE interest_rate_chart (
    id                             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    business_id                    uuid,
    name                           character varying(100) NOT NULL,
    description                    character varying(500),
    from_date                      date NOT NULL,
    end_date                       date,
    is_primary_grouping_by_amount  boolean NOT NULL DEFAULT false,
    created_by                     uuid,
    created_at                     timestamptz NOT NULL DEFAULT now(),
    updated_by                     uuid,
    updated_at                     timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE interest_rate_slab (
    id                     uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    business_id            uuid,
    chart_id               uuid NOT NULL REFERENCES interest_rate_chart(id) ON DELETE CASCADE,
    description            character varying(500),
    period_type            integer,         -- tenure unit for from/to_period: 0=days,1=months,2=years
    from_period            integer,
    to_period              integer,
    amount_range_from      numeric(19,6),
    amount_range_to        numeric(19,6),
    annual_interest_rate   numeric(19,6) NOT NULL,
    currency_code          character varying(3) NOT NULL,
    created_by             uuid,
    created_at             timestamptz NOT NULL DEFAULT now(),
    updated_by             uuid,
    updated_at             timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_interest_rate_slab_chart ON interest_rate_slab(chart_id);

-- ---------------------------------------------------------------------------
-- Savings/FD/RD share one product family, discriminated by deposit_type —
-- this mirrors Fineract's own m_savings_product design (FD/RD products are
-- savings products with extra term/pre-closure configuration), adapted to
-- a single flattened table rather than Fineract's product+deposit_details
-- join, since every column here is single-valued per product.
-- ---------------------------------------------------------------------------
CREATE TABLE savings_product (
    id                                       uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    business_id                              uuid,
    deposit_type                             integer NOT NULL DEFAULT 100, -- 100=SAVINGS,200=FIXED_DEPOSIT,300=RECURRING_DEPOSIT
    name                                     character varying(100) NOT NULL,
    short_name                               character varying(4) NOT NULL,
    description                              character varying(500),
    currency_code                            character varying(3) NOT NULL,
    digits_after_decimal                     integer NOT NULL DEFAULT 2,
    in_multiples_of                          integer NOT NULL DEFAULT 1,
    nominal_annual_interest_rate             numeric(19,6) NOT NULL,
    interest_compounding_period_type         integer NOT NULL DEFAULT 1,  -- 1=daily,4=monthly,5=quarterly,6=semiAnnual,7=annual
    interest_posting_period_type             integer NOT NULL DEFAULT 4,
    interest_calculation_type                integer NOT NULL DEFAULT 1,  -- 1=dailyBalance,2=averageDailyBalance
    interest_calculation_days_in_year_type   integer NOT NULL DEFAULT 365,
    min_required_opening_balance             numeric(19,6),
    lockin_period_frequency                  integer,
    lockin_period_frequency_type             integer,
    withdrawal_fee_for_transfer              boolean NOT NULL DEFAULT false,
    allow_overdraft                          boolean NOT NULL DEFAULT false,
    overdraft_limit                          numeric(19,6),
    min_balance_for_interest_calculation     numeric(19,6),
    min_required_balance                     numeric(19,6),
    enforce_min_required_balance             boolean NOT NULL DEFAULT false,
    is_dormancy_tracking_active              boolean NOT NULL DEFAULT false,
    days_to_inactive                         integer,
    days_to_dormancy                         integer,
    days_to_escheat                          integer,
    accounting_type                          integer NOT NULL DEFAULT 1,  -- 1=none,2=cash,3=accrual (see service header: posting is via outbox events, not live GL calls)
    interest_rate_chart_id                   uuid REFERENCES interest_rate_chart(id),
    -- FD/RD-only configuration (NULL for plain SAVINGS products):
    pre_closure_penal_applicable             boolean,
    pre_closure_penal_interest               numeric(19,6),
    pre_closure_penal_interest_on_type       integer,          -- 1=wholeTerm,2=tillPrematureWithdrawal
    min_deposit_term                         integer,
    min_deposit_term_type                    integer,
    max_deposit_term                         integer,
    max_deposit_term_type                    integer,
    in_multiples_of_deposit_term             integer,
    in_multiples_of_deposit_term_type        integer,
    is_mandatory_deposit                     boolean,          -- RD only
    allow_withdrawal                         boolean,          -- RD only: allow partial withdrawal before maturity
    adjust_advance_towards_future_payments   boolean,          -- RD only
    is_active                                boolean NOT NULL DEFAULT true,
    created_by                               uuid,
    created_at                               timestamptz NOT NULL DEFAULT now(),
    updated_by                               uuid,
    updated_at                               timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_savings_product_short_name UNIQUE (short_name)
);
CREATE INDEX idx_savings_product_deposit_type ON savings_product(deposit_type);

CREATE TABLE savings_product_charge (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    product_id  uuid NOT NULL REFERENCES savings_product(id) ON DELETE CASCADE,
    charge_id   uuid NOT NULL REFERENCES charge(id),
    CONSTRAINT uq_savings_product_charge UNIQUE (product_id, charge_id)
);

-- ---------------------------------------------------------------------------
-- Savings/FD/RD accounts (one table family, discriminated by deposit_type,
-- same rationale as savings_product above).
-- ---------------------------------------------------------------------------
CREATE TABLE savings_account (
    id                                       uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    business_id                              uuid,
    account_no                               character varying(20),
    external_id                              character varying(100),
    deposit_type                             integer NOT NULL DEFAULT 100,
    client_id                                uuid,   -- cross-service ref -> Customer.client.id (opaque, trusted; no sync HTTP client exists)
    group_id                                 uuid,   -- cross-service ref -> future Group service (opaque)
    product_id                               uuid NOT NULL REFERENCES savings_product(id),
    field_officer_id                         uuid,   -- cross-service ref -> Organization.staff.id (opaque)
    status                                   integer NOT NULL DEFAULT 100, -- 100=submittedAndPendingApproval,200=approved,300=active,400=withdrawnByClient,500=rejected,600=closed,601=prematureClosed,602=matured
    sub_status                               integer NOT NULL DEFAULT 0,   -- 0=none,1=inactive,2=dormant,3=escheat,4=block,5=blockCredit,6=blockDebit
    account_type                             integer NOT NULL DEFAULT 1,   -- 1=individual,2=group,3=jlg
    currency_code                            character varying(3) NOT NULL,
    digits_after_decimal                     integer NOT NULL DEFAULT 2,
    in_multiples_of                          integer NOT NULL DEFAULT 1,
    nominal_annual_interest_rate             numeric(19,6) NOT NULL,
    interest_compounding_period_type         integer NOT NULL DEFAULT 1,
    interest_posting_period_type             integer NOT NULL DEFAULT 4,
    interest_calculation_type                integer NOT NULL DEFAULT 1,
    interest_calculation_days_in_year_type   integer NOT NULL DEFAULT 365,
    min_required_opening_balance             numeric(19,6),
    lockin_period_frequency                  integer,
    lockin_period_frequency_type             integer,
    withdrawal_fee_for_transfer              boolean NOT NULL DEFAULT false,
    allow_overdraft                          boolean NOT NULL DEFAULT false,
    overdraft_limit                          numeric(19,6),
    min_balance_for_interest_calculation     numeric(19,6),
    min_required_balance                     numeric(19,6),
    enforce_min_required_balance             boolean NOT NULL DEFAULT false,
    submitted_on_date                        date,
    submitted_by                             uuid,
    approved_on_date                         date,
    approved_by                              uuid,
    activated_on_date                        date,
    activated_by                             uuid,
    rejected_on_date                         date,
    rejected_by                              uuid,
    withdrawn_on_date                        date,
    withdrawn_by                             uuid,
    closed_on_date                           date,
    closed_by                                uuid,
    account_balance_derived                  numeric(19,6) NOT NULL DEFAULT 0,
    total_deposits_derived                   numeric(19,6) NOT NULL DEFAULT 0,
    total_withdrawals_derived                numeric(19,6) NOT NULL DEFAULT 0,
    total_interest_posted_derived            numeric(19,6) NOT NULL DEFAULT 0,
    total_fee_charge_derived                 numeric(19,6) NOT NULL DEFAULT 0,
    total_withdrawal_fee_derived             numeric(19,6) NOT NULL DEFAULT 0,
    last_interest_calculation_date           date,
    is_credit_blocked                        boolean NOT NULL DEFAULT false,
    is_debit_blocked                         boolean NOT NULL DEFAULT false,
    is_interest_blocked                      boolean NOT NULL DEFAULT false,
    parent_account_id                        uuid REFERENCES savings_account(id), -- GSIM parent linkage (thin-stub scope, see service header)
    is_gsim_parent                           boolean NOT NULL DEFAULT false,
    created_by                               uuid,
    created_at                               timestamptz NOT NULL DEFAULT now(),
    updated_by                               uuid,
    updated_at                               timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_savings_account_no UNIQUE (account_no),
    CONSTRAINT uq_savings_account_external_id UNIQUE (external_id)
);
CREATE INDEX idx_savings_account_client ON savings_account(client_id);
CREATE INDEX idx_savings_account_product ON savings_account(product_id);
CREATE INDEX idx_savings_account_status ON savings_account(status);
CREATE INDEX idx_savings_account_deposit_type ON savings_account(deposit_type);

CREATE TABLE savings_account_transaction (
    id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    business_id                uuid,
    savings_account_id         uuid NOT NULL REFERENCES savings_account(id),
    transaction_type           integer NOT NULL, -- 1=deposit,2=withdrawal,10=interestPosting,5=withdrawalFee,6=annualFee,7=feeCharge,8=penaltyCharge,9=overdraftInterest,12=waiveCharge,20=transferIn,21=transferOut,22=amountHold,23=amountRelease
    transaction_date           date NOT NULL,
    amount                     numeric(19,6) NOT NULL,
    running_balance_derived    numeric(19,6) NOT NULL,
    overdraft_amount_derived   numeric(19,6) NOT NULL DEFAULT 0,
    is_reversed                boolean NOT NULL DEFAULT false,
    is_hold_transaction        boolean NOT NULL DEFAULT false,
    release_id_of_hold         uuid REFERENCES savings_account_transaction(id),
    payment_detail_id          uuid,    -- cross-service ref -> Organization payment-type/detail (opaque)
    submitted_on_date          date NOT NULL DEFAULT CURRENT_DATE,
    description                character varying(500),
    created_by                 uuid,
    created_at                 timestamptz NOT NULL DEFAULT now(),
    updated_by                 uuid,
    updated_at                 timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_sat_account ON savings_account_transaction(savings_account_id);
CREATE INDEX idx_sat_date ON savings_account_transaction(transaction_date);

CREATE TABLE savings_account_charge (
    id                            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    business_id                   uuid,
    savings_account_id            uuid NOT NULL REFERENCES savings_account(id),
    charge_id                     uuid NOT NULL REFERENCES charge(id),
    charge_time_type              integer NOT NULL,
    due_date                      date,
    fee_interval                  integer,
    amount                        numeric(19,6) NOT NULL,
    amount_paid_derived           numeric(19,6) NOT NULL DEFAULT 0,
    amount_waived_derived         numeric(19,6) NOT NULL DEFAULT 0,
    amount_outstanding_derived    numeric(19,6) NOT NULL DEFAULT 0,
    is_paid_derived               boolean NOT NULL DEFAULT false,
    is_waived                     boolean NOT NULL DEFAULT false,
    is_active                     boolean NOT NULL DEFAULT true,
    inactivated_on_date           date,
    created_by                    uuid,
    created_at                    timestamptz NOT NULL DEFAULT now(),
    updated_by                    uuid,
    updated_at                    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_sac_account ON savings_account_charge(savings_account_id);

-- ---------------------------------------------------------------------------
-- FD/RD-only term & pre-closure details (1:1 with savings_account where
-- deposit_type != SAVINGS).
-- ---------------------------------------------------------------------------
CREATE TABLE deposit_account_term_and_preclosure (
    id                                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    savings_account_id                  uuid NOT NULL REFERENCES savings_account(id),
    deposit_amount                      numeric(19,6),
    deposit_period                      integer,
    deposit_period_frequency_type       integer,  -- 0=days,1=months,2=years
    maturity_amount                     numeric(19,6),
    maturity_date                       date,
    expected_firstdeposit_on_date       date,      -- RD only
    is_renewal_allowed                  boolean NOT NULL DEFAULT false,
    is_premature_closure_allowed        boolean NOT NULL DEFAULT true,
    pre_closure_penal_applicable        boolean NOT NULL DEFAULT false,
    pre_closure_penal_interest          numeric(19,6),
    pre_closure_penal_interest_on_type  integer,
    on_account_closure_type             integer,   -- FD: 100=withdrawDeposit,200=transferToSavings,400=reinvest
    transfer_to_savings_account_id      uuid REFERENCES savings_account(id),
    created_by                          uuid,
    created_at                          timestamptz NOT NULL DEFAULT now(),
    updated_by                          uuid,
    updated_at                          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_deposit_term_account UNIQUE (savings_account_id)
);

CREATE TABLE recurring_deposit_schedule_installment (
    id                                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    savings_account_id                uuid NOT NULL REFERENCES savings_account(id),
    installment_number                 integer NOT NULL,
    due_date                           date NOT NULL,
    deposit_amount                     numeric(19,6) NOT NULL,
    deposit_amount_completed_derived   numeric(19,6) NOT NULL DEFAULT 0,
    is_obligation_met                  boolean NOT NULL DEFAULT false,
    obligation_met_on_date             date,
    created_at                         timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_rd_installment UNIQUE (savings_account_id, installment_number)
);
CREATE INDEX idx_rd_installment_account ON recurring_deposit_schedule_installment(savings_account_id);

-- ---------------------------------------------------------------------------
-- Account transfers (internal, atomic two-leg postings between accounts).
-- account_type: 2=SAVINGS (resolvable to a savings_account row in this
-- service's own DB); 1=LOAN is accepted as an opaque cross-service id
-- (Portfolio doesn't exist yet — see service header) exactly like other
-- phases' trusted cross-service ids.
-- ---------------------------------------------------------------------------
CREATE TABLE account_transfer_details (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    business_id         uuid,
    from_office_id      uuid,   -- cross-service ref -> Organization.office.id (opaque)
    from_client_id      uuid,   -- cross-service ref -> Customer.client.id (opaque)
    from_account_type   integer NOT NULL,
    from_account_id     uuid NOT NULL,
    to_office_id        uuid,
    to_client_id        uuid,
    to_account_type     integer NOT NULL,
    to_account_id       uuid NOT NULL,
    transfer_type        integer NOT NULL DEFAULT 1, -- 1=accountTransfer,2=loanRefund
    created_by          uuid,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_by          uuid,
    updated_at          timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE account_transfer_transaction (
    id                             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    business_id                    uuid,
    account_transfer_details_id    uuid NOT NULL REFERENCES account_transfer_details(id),
    from_transaction_id             uuid REFERENCES savings_account_transaction(id),
    to_transaction_id               uuid REFERENCES savings_account_transaction(id),
    transaction_date                date NOT NULL,
    transaction_amount              numeric(19,6) NOT NULL,
    description                     character varying(500),
    is_reversed                     boolean NOT NULL DEFAULT false,
    created_by                      uuid,
    created_at                      timestamptz NOT NULL DEFAULT now(),
    updated_by                      uuid,
    updated_at                      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_att_details ON account_transfer_transaction(account_transfer_details_id);

-- ---------------------------------------------------------------------------
-- Standing instructions (recurring/dues-triggered account transfers).
-- ---------------------------------------------------------------------------
CREATE TABLE standing_instruction (
    id                      uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    business_id             uuid,
    name                    character varying(100) NOT NULL,
    description             character varying(500),
    client_id               uuid,  -- cross-service ref -> Customer.client.id (opaque)
    from_office_id          uuid,
    from_client_id          uuid,
    from_account_type       integer NOT NULL,
    from_account_id         uuid NOT NULL,
    to_office_id            uuid,
    to_client_id            uuid,
    to_account_type         integer NOT NULL,
    to_account_id           uuid NOT NULL,
    instruction_type        integer NOT NULL DEFAULT 1, -- 1=duesPayment,2=fixedAmount
    status                  integer NOT NULL DEFAULT 300, -- 300=active,600=disabled/expired
    priority                integer NOT NULL DEFAULT 1,
    transfer_type           integer NOT NULL DEFAULT 1,
    amount                  numeric(19,6),
    valid_from              date NOT NULL,
    valid_till              date,
    recurrence_type         integer NOT NULL DEFAULT 1, -- 1=periodic,2=duesPaymentTriggered
    recurrence_frequency    integer,                     -- 1=months,2=weeks,3=days
    recurrence_interval     integer,
    recurrence_on_day       integer,
    last_run_date           date,
    created_by              uuid,
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_by              uuid,
    updated_at              timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_standing_instruction_client ON standing_instruction(client_id);
CREATE INDEX idx_standing_instruction_status ON standing_instruction(status);

CREATE TABLE standing_instruction_history (
    id                                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    standing_instruction_id            uuid NOT NULL REFERENCES standing_instruction(id),
    status                             integer NOT NULL, -- 0=success,1=failed
    amount                             numeric(19,6),
    execution_date                     date NOT NULL DEFAULT CURRENT_DATE,
    error_log                          character varying(1000),
    account_transfer_transaction_id    uuid REFERENCES account_transfer_transaction(id),
    created_at                         timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_sih_instruction ON standing_instruction_history(standing_instruction_id);
